<?php declare(strict_types=1);use App\Helpers\View;$e=static fn($x)=>htmlspecialchars((string)$x,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');ob_start();?><div class="btp-shell btp-workspace"><nav class="btp-breadcrumb"><a href="<?= $e(View::url('btp/debourses')) ?>">Déboursés</a><span>/</span><strong>Nouveau</strong></nav><header class="btp-banner"><small>CHIFFRAGE DES COÛTS</small><h1><i class="fa-solid fa-calculator"></i> Nouveau déboursé prévisionnel</h1><p>Chaque ligne du bon de commande est reprise automatiquement.</p></header><?php if($errorBtp): ?><p class="btp-error" role="alert"><?= $e($errorBtp) ?></p><?php endif; ?><section class="btp-panel btp-section"><form method="get" action="<?= $e(View::url('btp/debourses/nouveau')) ?>"><label>Bon de commande <select name="bc" required data-select-search data-placeholder="Rechercher une référence de BC ou un client"><option value="">Sélectionner</option><?php foreach($ordersBtp as $bc): ?><option value="<?= (int)$bc['id'] ?>" <?= $selectedOrderBtp&&(int)$selectedOrderBtp['id']===(int)$bc['id']?'selected':'' ?>><?= $e($bc['reference'].' · '.$bc['project_reference'].' · '.$bc['client_nom']) ?></option><?php endforeach; ?></select></label><button type="submit">Charger les lignes</button></form></section><?php if($selectedOrderBtp): ?><form method="post" action="<?= $e(View::url('btp/debourses')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrfBtp) ?>"><input type="hidden" name="order_id" value="<?= (int)$selectedOrderBtp['id'] ?>"><section class="btp-panel btp-section"><h2>BC <?= $e($selectedOrderBtp['reference']) ?> · Devis révision <?= (int)$selectedOrderBtp['quote_revision'] ?></h2><p class="btp-help">Prix de vente HT : <?= number_format((float)$selectedOrderBtp['amount_ht'],2,',',' ') ?> FCFA. Renseignez les coûts totaux de chaque ligne, pas les prix unitaires.</p><div class="btp-table-wrap"><table class="btp-editor-table"><thead><tr><th>Désignation</th><th>Quantité</th><th>Vente HT</th><th>Matériaux</th><th>Main-d'œuvre</th><th>Matériel</th><th>Sous-traitance</th><th>Autres</th></tr></thead><tbody><?php foreach($orderLinesBtp as $l): ?><tr><td><?= $e($l['description']) ?></td><td><?= $e($l['quantity'].' '.$l['unit']) ?></td><td><?= number_format((float)$l['line_total'],2,',',' ') ?></td><?php foreach(['materials','labor','equipment','subcontracting','other_cost'] as $field): ?><td><input type="number" name="costs[<?= (int)$l['id'] ?>][<?= $e($field) ?>]" min="0" max="999999999999" step=".01" value="0" required aria-label="<?= $e($field.' · '.$l['description']) ?>" style="min-width:110px;width:100%"></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><p class="btp-help">Chaque enregistrement crée une nouvelle révision de déboursé en brouillon. La validation financière sera une étape distincte.</p><button type="submit">Enregistrer le déboursé</button></section></form><?php endif; ?></div><?php $content=ob_get_clean();$additionalScripts=array_merge($additionalScripts??[],['js/components/form-components.js']);require BASE_PATH.'/views/layouts/module.php';